import { render } from "astro:content";
import Layout from "../../layouts/Layout.astro";
import ArticleMeta from "../../components/articles/ArticleMeta.astro";
import { AUDIO_BASE, socialLinks } from "../../consts";
import { getArticles, readingMinutes } from "../../lib/articles";

export async function getStaticPaths() {
  const articles = await getArticles();
  return articles.map((article) => ({ params: { slug: article.id }, props: { article, articles } }));
}

const { article, articles } = Astro.props;
const { title, description, pubDate, updatedDate, tags, narrated, originalAudio, shared } = article.data;
const { Content } = await render(article);
const more = articles.filter((other) => other.id !== article.id).slice(0, 2);
const audio = `${AUDIO_BASE}/${article.id}.mp3`;

const url = new URL(Astro.url.pathname, Astro.site);
const ogImage = `/og/articles/${article.id}.png`;
const minutes = readingMinutes(article);
const author = {
  "@type": "Person",
  name: "Sara Natour",
  url: Astro.site,
  jobTitle: "Full-stack developer",
  sameAs: socialLinks.filter(({ label }) => label !== "email").map(({ url }) => url),
};

// Structured data for search engines and answer engines: the article itself, and where it sits on the site.
const jsonLd = [
  {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    "@id": `${url}#article`,
    headline: title,
    description,
    image: new URL(ogImage, Astro.site),
    datePublished: pubDate.toISOString(),
    dateModified: (updatedDate ?? pubDate).toISOString(),
    author,
    publisher: author,
    mainEntityOfPage: url,
    url,
    inLanguage: "en",
    wordCount: (article.body ?? "").split(/\s+/).filter(Boolean).length,
    timeRequired: `PT${minutes}M`,
    isAccessibleForFree: true,
    ...(tags.length && { keywords: tags.join(", ") }),
    ...(shared.length && { sameAs: shared.map(({ url }) => url) }),
    ...(narrated && {
      audio: { "@type": "AudioObject", contentUrl: audio, encodingFormat: "audio/mpeg", name: `${title}, read by Sara Natour` },
    }),
  },
  {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: Astro.site },
      { "@type": "ListItem", position: 2, name: "Articles", item: new URL("/articles", Astro.site) },
      { "@type": "ListItem", position: 3, name: title, item: url },
    ],
  },
];
